#include "TitleScanner.hpp"
#include "Smdh.hpp"
#include <cstdio>
#include <cstdlib>
#include <vector>
namespace {
std::string Hex16(u64 id){char b[17];std::snprintf(b,sizeof(b),"%016llX",(unsigned long long)id);return b;}
std::string Media(FS_MediaType m){return m==MEDIATYPE_NAND?"NAND":m==MEDIATYPE_SD?"SD":"GAME_CARD";}
std::string Kind(u64 id){u32 hi=u32(id>>32);if(hi==0x00040000)return"GAME";if(hi==0x00040002)return"DEMO";if(hi==0x0004000E)return"UPDATE";if(hi==0x0004008C)return"DLC";if((hi&0xFFFFFF00)==0x00048000)return"DSIWARE_OR_TWL";if((hi&0xFFFFFF00)==0x00040100||hi==0x00040010||hi==0x0004001B||hi==0x00040030||hi==0x0004009B||hi==0x000400DB)return"SYSTEM";return"OTHER";}
std::string Parent(u64 id,const std::string&k){if(k!="UPDATE"&&k!="DLC")return Hex16(id);return Hex16((0x00040000ULL<<32)|(id&0xFFFFFFFFULL));}
const char* Regions[]={"Japan","North America","Europe","Australia","China","Korea","Taiwan"};
std::string RegionString(u32 mask){if(!mask)return"Unknown";if((mask&0x7F)==0x7F)return"Region Free";std::string out;for(int i=0;i<7;++i)if(mask&(1u<<i)){if(!out.empty())out+=", ";out+=Regions[i];}return out.empty()?"Unknown":out;}
CFG_Language DefaultLanguage(){u8 lang=CFG_LANGUAGE_EN;if(R_SUCCEEDED(CFGU_GetSystemLanguage(&lang)))return CFG_Language(lang);u8 region=CFG_REGION_EUR;CFGU_SecureInfoGetRegion(&region);static const CFG_Language defaults[]={CFG_LANGUAGE_JP,CFG_LANGUAGE_EN,CFG_LANGUAGE_EN,CFG_LANGUAGE_EN,CFG_LANGUAGE_ZH,CFG_LANGUAGE_KO,CFG_LANGUAGE_ZH};return region<7?defaults[region]:CFG_LANGUAGE_EN;}
std::string Utf16(const u16*src,size_t units){std::vector<u8> out(units*3+1);ssize_t n=utf16_to_utf8(out.data(),src,out.size());if(n<0)return{};return std::string((char*)out.data());}
bool Empty(const u16*s,size_t n){for(size_t i=0;i<n;++i)if(s[i])return false;return true;}
int PickTitle(const GV_Smdh&s){int preferred=int(DefaultLanguage());if(preferred>=0&&preferred<16&&!Empty(s.titles[preferred].shortDescription,0x40))return preferred;for(int i=0;i<16;++i)if(!Empty(s.titles[i].shortDescription,0x40))return i;return preferred>=0&&preferred<16?preferred:1;}
Result LoadSmdh(u64 id,FS_MediaType media,GV_Smdh&out){static const u32 filePathData[5]={0,0,2,0x6E6F6369,0};u32 archivePathData[4]={u32(id),u32(id>>32),u32(media),0};FS_Path archivePath={PATH_BINARY,sizeof(archivePathData),archivePathData};FS_Path filePath={PATH_BINARY,sizeof(filePathData),filePathData};Handle h=0;Result rc=FSUSER_OpenFileDirectly(&h,ARCHIVE_SAVEDATA_AND_CONTENT,archivePath,filePath,FS_OPEN_READ,0);if(R_FAILED(rc))return rc;u32 read=0;rc=FSFILE_Read(h,&read,0,&out,sizeof(out));FSFILE_Close(h);if(R_SUCCEEDED(rc)&&read!=sizeof(out))return -1;return rc;}
void AddSmdh(ExportTitle&t,FS_MediaType media,ScanSummary&s){if(t.kind=="SYSTEM"||t.kind=="DSIWARE_OR_TWL")return;GV_Smdh smdh{};Result rc=LoadSmdh(t.titleId,media,smdh);t.smdhResult=(int32_t)rc;if(R_FAILED(rc)){++s.smdhMissing;return;}int i=PickTitle(smdh);t.name=Utf16(smdh.titles[i].shortDescription,0x40);t.longDescription=Utf16(smdh.titles[i].longDescription,0x80);t.publisher=Utf16(smdh.titles[i].publisher,0x40);t.regionMask=smdh.settings.region;t.region=RegionString(t.regionMask);t.smdhAvailable=true;++s.smdhSuccess;}
bool ScanMedia(FS_MediaType media,std::vector<ExportTitle>&out,u32&countOut,std::vector<std::string>&errors,ScanSummary&s,bool optional){u32 count=0;Result rc=AM_GetTitleCount(media,&count);if(R_FAILED(rc)){if(optional){countOut=0;return true;}char b[96];snprintf(b,sizeof(b),"AM_GetTitleCount %s: 0x%08lX",Media(media).c_str(),(unsigned long)rc);errors.emplace_back(b);return false;}countOut=count;if(media==MEDIATYPE_GAME_CARD)s.gameCardPresent=count>0;if(!count)return true;std::vector<u64>ids(count);u32 read=0;rc=AM_GetTitleList(&read,media,count,ids.data());if(R_FAILED(rc)){if(optional)return true;return false;}ids.resize(read);std::vector<AM_TitleEntry>info(read);rc=AM_GetTitleInfo(media,read,ids.data(),info.data());if(R_FAILED(rc)){if(optional)return true;return false;}for(const auto&e:info){ExportTitle t;t.titleId=e.titleID;t.size=e.size;t.version=e.version;t.mediaType=Media(media);t.kind=Kind(t.titleId);t.parentTitleId=Parent(t.titleId,t.kind);AddSmdh(t,media,s);out.push_back(std::move(t));}return true;}
}
bool ScanTitles(std::vector<ExportTitle>&titles,ScanSummary&s){titles.clear();s={};bool ok=true;ok=ScanMedia(MEDIATYPE_NAND,titles,s.nandCount,s.errors,s,false)&&ok;ok=ScanMedia(MEDIATYPE_SD,titles,s.sdCount,s.errors,s,false)&&ok;ScanMedia(MEDIATYPE_GAME_CARD,titles,s.gameCardCount,s.errors,s,true);return ok;}
